#[test]
fn from_str_base_unit() {
    let abbr = RotationalStiffnessUnit::NewtonMeterPerRadian.abbreviation();
    let s = format!("1 {}", abbr);
    let parsed: RotationalStiffness = s.parse().expect("parse failed");
    let expected = RotationalStiffness::from_newton_meters_per_radian(1.0).as_base();
    assert!((parsed.as_base() - expected).abs() / expected.abs().max(1.0) < RT_EPS);
}
